import { localStorageDriver } from "./local";

// The CMS and content model only ever hold storage KEYS (see media_asset.key) and call this interface.
// To move to S3-compatible storage: implement MediaStorage in ./s3.ts, add a case below, set STORAGE_DRIVER=s3.
export interface MediaStorage {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(keys: string[]): Promise<void>;
}
// Keys are generated by the server only: <uuid>[-<width>].<ext>. Anything else is rejected, which also blocks path traversal.
export const KEY_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(-\d{3,4})?\.(jpg|png|webp)$/;
export const CONTENT_TYPES: Record<string, string> = { jpg: "image/jpeg", png: "image/png", webp: "image/webp" };

export function getStorage(): MediaStorage {
  const driver = process.env.STORAGE_DRIVER ?? "local";
  if (driver === "local") return localStorageDriver;
  throw new Error(`Unsupported STORAGE_DRIVER "${driver}". Implement MediaStorage in src/lib/storage/${driver}.ts.`);
}
// Single place that turns a key into a public URL. Point MEDIA_PUBLIC_BASE at a CDN/bucket URL later; the app route /media/<key> is the default.
export const mediaUrl = (key: string) => (process.env.MEDIA_PUBLIC_BASE ? `${process.env.MEDIA_PUBLIC_BASE.replace(/\/$/, "")}/${key}` : `/media/${key}`);
export const variantKeys = (key: string, widths: number[]) => widths.map((w) => `${key.replace(/\.\w+$/, "")}-${w}.webp`);
